use std::collections::VecDeque;
use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use std::time::Duration;

/// A bounded work queue supporting cancellation.
///
/// - `push` blocks when the queue is full.
/// - `pop` blocks when the queue is empty.
/// - After `close()`, `push` fails and `pop` drains remaining items then returns `None`.
pub struct BoundedQueue<T> {
    inner: Arc<Shared<T>>,
}

struct Shared<T> {
    state: Mutex<State<T>>,
    not_empty: Condvar,
    not_full: Condvar,
}

struct State<T> {
    items: VecDeque<T>,
    capacity: usize,
    closed: bool,
}

impl<T> BoundedQueue<T> {
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be greater than zero");
        BoundedQueue {
            inner: Arc::new(Shared {
                state: Mutex::new(State {
                    items: VecDeque::with_capacity(capacity),
                    capacity,
                    closed: false,
                }),
                not_empty: Condvar::new(),
                not_full: Condvar::new(),
            }),
        }
    }

    /// Push an item, blocking while the queue is full.
    /// Returns `Err(item)` if the queue is closed.
    pub fn push(&self, item: T) -> Result<(), T> {
        let mut state = self.inner.state.lock().unwrap();
        loop {
            if state.closed {
                return Err(item);
            }
            if state.items.len() < state.capacity {
                state.items.push_back(item);
                self.inner.not_empty.notify_one();
                return Ok(());
            }
            state = self.inner.not_full.wait(state).unwrap();
        }
    }

    /// Pop an item, blocking while the queue is empty.
    /// Returns `None` when the queue is closed and drained.
    pub fn pop(&self) -> Option<T> {
        let mut state = self.inner.state.lock().unwrap();
        loop {
            match state.items.pop_front() {
                Some(item) => {
                    self.inner.not_full.notify_one();
                    return Some(item);
                }
                None => {
                    if state.closed {
                        return None;
                    }
                    state = self.inner.not_empty.wait(state).unwrap();
                }
            }
        }
    }

